// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.junit.jupiter.api.Test;

class PackedCostSessionLifecycleTest {

	@Test
	void coldPlanningOpensOneSessionUsesItForEveryCostingPhaseAndClosesIt() {
		SessionOnlyCostModel model = new SessionOnlyCostModel(false);

		PackedPlanningResult result = PackedCascadesPlanner.optimize(query(), OptimizationGoal.root(), model);

		assertNotNull(result.selectedPlan());
		assertEquals(1, model.openCount);
		assertEquals(1, model.closeCount);
		assertTrue(model.leafCount > 0, "cold planning must route isolated estimates through the session");
		assertTrue(model.appendCount > 0, "join enumeration must route prefix extensions through the session");
		assertTrue(model.operatorCount > 0, "non-leaf refinement must route through the session");
		assertEquals(0, model.directCallCount, "the planner must not bypass its query-local session");
	}

	@Test
	void coldPlanningClosesTheSessionWhenAProviderFailsMidSearch() {
		SessionOnlyCostModel model = new SessionOnlyCostModel(true);

		ProviderFailure failure = assertThrows(ProviderFailure.class,
				() -> PackedCascadesPlanner.optimize(query(), OptimizationGoal.root(), model));

		assertEquals("deliberate append failure", failure.getMessage());
		assertEquals(1, model.openCount);
		assertEquals(1, model.closeCount, "query-local state must close when costing aborts");
		assertTrue(model.leafCount > 0, "the failure must occur after the session has begun costing");
		assertEquals(1, model.appendCount);
		assertEquals(0, model.directCallCount, "even the exceptional path must not bypass the session");
	}

	@Test
	void defaultScalarLambdaSessionPreservesPlanRowsAndCost() {
		TupleExpr source = query();
		PackedCostModel scalar = PackedCostSessionLifecycleTest::rows;
		PackedPlanningResult scalarResult = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), scalar);
		SessionOnlyCostModel sessionOnly = new SessionOnlyCostModel(false);

		PackedPlanningResult sessionResult = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(),
				sessionOnly);

		assertEquals(scalarResult.selectedPlan(), sessionResult.selectedPlan());
		assertEquals(scalarResult.outputRows(), sessionResult.outputRows(), 0.0d);
		assertEquals(scalarResult.totalCost(), sessionResult.totalCost(), 0.0d);
		assertEquals(1, sessionOnly.openCount);
		assertEquals(1, sessionOnly.closeCount);
		assertEquals(0, sessionOnly.directCallCount);
	}

	private static TupleExpr query() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern large = pattern(values, "person", "urn:large", "largeValue");
		StatementPattern tail = pattern(values, "bridge", "urn:tail", "tailValue");
		StatementPattern bridge = pattern(values, "person", "urn:bridge", "bridge");
		return new Join(new Join(large, tail), bridge);
	}

	private static StatementPattern pattern(SimpleValueFactory values, String subject, String predicate,
			String object) {
		return new StatementPattern(Var.of(subject), Var.of("predicate", values.createIRI(predicate)), Var.of(object));
	}

	private static double rows(PackedQueryView query, int relationId) {
		if (!query.isStatementPattern(relationId)) {
			return Double.NaN;
		}
		return switch (query.statementPatternValue(relationId, 1).stringValue()) {
		case "urn:large" -> 1_000.0d;
		case "urn:bridge" -> 10.0d;
		case "urn:tail" -> 4.0d;
		default -> Double.NaN;
		};
	}

	private static final class SessionOnlyCostModel implements PackedCostModel {

		private final boolean failOnFirstAppend;
		private int openCount;
		private int closeCount;
		private int leafCount;
		private int appendCount;
		private int operatorCount;
		private int directCallCount;

		private SessionOnlyCostModel(boolean failOnFirstAppend) {
			this.failOnFirstAppend = failOnFirstAppend;
		}

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			throw directCall();
		}

		@Override
		public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			throw directCall();
		}

		@Override
		public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
				PackedCostEstimate output) {
			throw directCall();
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			openCount++;
			return new PackedCostSession() {
				@Override
				public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
					leafCount++;
					writeRows(query, relationId, output);
				}

				@Override
				public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
					appendCount++;
					if (failOnFirstAppend && appendCount == 1) {
						throw new ProviderFailure("deliberate append failure");
					}
					writeRows(query, relationId, output);
				}

				@Override
				public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					operatorCount++;
				}

				@Override
				public void close() {
					closeCount++;
				}
			};
		}

		private AssertionError directCall() {
			directCallCount++;
			return new AssertionError("packed planner bypassed its query-local cost session");
		}

		private static void writeRows(PackedQueryView query, int relationId, PackedCostEstimate output) {
			double rows = rows(query, relationId);
			if (Double.isFinite(rows)) {
				output.setRows(rows, rows);
			}
		}
	}

	private static final class ProviderFailure extends RuntimeException {

		private static final long serialVersionUID = 1L;

		private ProviderFailure(String message) {
			super(message);
		}
	}
}
